package com.example.techfix.activities;

import android.os.Bundle;import android.text.Editable;import android.text.TextWatcher;import android.widget.Toast;import android.widget.Spinner;import android.widget.AdapterView;import androidx.appcompat.app.AppCompatActivity;import androidx.recyclerview.widget.LinearLayoutManager;import androidx.recyclerview.widget.RecyclerView;import com.example.techfix.R;import com.example.techfix.adapters.ServiceAdapter;import com.example.techfix.database.DatabaseHelper;import com.google.android.material.textfield.TextInputEditText;import java.util.ArrayList;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;
public class ServicesActivity extends AppCompatActivity{private final ExecutorService io=Executors.newSingleThreadExecutor();private DatabaseHelper db;private ServiceAdapter adapter;@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_services);db=new DatabaseHelper(this);RecyclerView list=findViewById(R.id.rvServices);list.setLayoutManager(new LinearLayoutManager(this));adapter=new ServiceAdapter(new ArrayList<>());list.setAdapter(adapter);findViewById(R.id.btnServicesBack).setOnClickListener(v->finish());TextInputEditText search=findViewById(R.id.etServiceSearch);Spinner category=findViewById(R.id.spinnerServiceCategory);category.setAdapter(new android.widget.ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"All","Mobile","Laptop","Desktop"}));category.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int pos,long id){load(search.getText()==null?"":search.getText().toString(),p.getItemAtPosition(pos).toString());}});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){load(s.toString(),category.getSelectedItem()==null?"All":category.getSelectedItem().toString());}public void afterTextChanged(Editable e){}});load("","All");}private void load(String q,String category){io.execute(()->{try{java.util.List<com.example.techfix.models.RepairService> data=db.getServices(q,category);runOnUiThread(()->adapter.update(data));}catch(Exception e){runOnUiThread(()->Toast.makeText(this,"Unable to load services",Toast.LENGTH_LONG).show());}});}@Override protected void onDestroy(){io.shutdown();db.close();super.onDestroy();}}
